<style>
.print-workspace{max-width:1400px;margin:auto;color:#152238;min-width:0}.print-workspace .print-hero{padding:28px;background:linear-gradient(120deg,#17243b,#253955);color:#fff;border-radius:20px;margin-bottom:20px}.print-workspace .eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:#aebed1}.print-workspace h2{font-size:26px;font-weight:700;line-height:1.25;margin:10px 0}.print-workspace .print-panel{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:24px;margin:18px 0;min-width:0}.print-workspace h3{font-size:18px;font-weight:700;margin-bottom:6px}.print-workspace .print-note{font-size:13px;color:#708097;line-height:1.7}.print-workspace .print-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:20px}.print-workspace .print-field{display:block;min-width:0;font-size:12px}.print-workspace .print-field>span{display:block;font-weight:600;margin-bottom:7px}.print-workspace input:not([type=checkbox]),.print-workspace select,.print-workspace textarea{width:100%;background:#f8fafc;color:#17243b;border:1px solid #dce4ee;border-radius:9px;padding:11px;font-size:13px;min-width:0}.print-workspace input:focus,.print-workspace select:focus,.print-workspace textarea:focus{outline:2px solid #efb7bc;outline-offset:1px}.print-workspace b{color:#da1e2d}.print-workspace .print-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.print-workspace .print-primary,.print-workspace .print-secondary{display:inline-block;padding:12px 18px;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer}.print-workspace .print-primary{background:#e50914;color:#fff;border:1px solid #e50914}.print-workspace .print-secondary{background:#fff;color:#17243b;border:1px solid #d4deeb}.print-workspace .print-item{border:1px solid #dde6f0;background:#fbfcfe;border-radius:12px;padding:18px;margin-top:20px}.print-workspace .print-item-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;margin-top:15px}.print-workspace .print-checks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin-top:20px}.print-workspace .print-checks label{font-size:13px;padding:14px;background:#f6f8fb;border-radius:10px;display:flex;gap:10px;align-items:start}.print-workspace .print-checks input{margin-top:3px;accent-color:#e50914}.print-workspace table{width:100%;border-collapse:collapse;font-size:13px}.print-workspace th,.print-workspace td{text-align:left;padding:15px;border-bottom:1px solid #e5ebf2;vertical-align:top}.print-workspace th{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7c92}.print-workspace .print-alert{background:#fff1f2;color:#9f1239;padding:18px;border:1px solid #fecdd3;border-radius:12px}.print-workspace .print-success{background:#ecfdf5;color:#065f46;padding:15px;border:1px solid #a7f3d0;border-radius:12px}.print-workspace .print-steps{display:flex;gap:18px;flex-wrap:wrap;margin-top:20px;font-size:12px;color:#bdcadd}.print-workspace .print-steps strong{color:#fff}.print-workspace .print-breadcrumb{color:#b6c3d4;font-size:12px;margin-bottom:16px;display:flex;gap:10px;flex-wrap:wrap}.print-workspace button:disabled{opacity:.45;cursor:not-allowed}.print-workspace [x-cloak]{display:none!important}@media(max-width:900px){.print-workspace .print-item-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.print-workspace .print-grid,.print-workspace .print-checks{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.print-workspace .print-grid,.print-workspace .print-checks,.print-workspace .print-item-grid{grid-template-columns:minmax(0,1fr)}.print-workspace .print-panel,.print-workspace .print-hero{padding:18px}.print-workspace h2{font-size:23px}}
